/* =========================================================================
   seed_50_people.sql
   AI-Integrated Claims Underwriting Dashboard — Synthetic Seed Data
   50 fictional claimants, policies, claims, bills, docs, and AI evaluations.
   Target: Microsoft SQL Server (T-SQL)
   NOTE: All names, IDs, and figures are synthetic/fictional test data.
   ========================================================================= */

IF DB_ID('ClaimsUnderwritingDB') IS NULL
BEGIN
    PRINT 'Run this script against an existing database, or CREATE DATABASE ClaimsUnderwritingDB first.';
END
GO

/* ---------- Schema ---------- */

IF OBJECT_ID('dbo.AIUnderwritingEvaluation','U') IS NOT NULL DROP TABLE dbo.AIUnderwritingEvaluation;
IF OBJECT_ID('dbo.ClaimSupportingDocs','U') IS NOT NULL DROP TABLE dbo.ClaimSupportingDocs;
IF OBJECT_ID('dbo.ClaimBills','U') IS NOT NULL DROP TABLE dbo.ClaimBills;
IF OBJECT_ID('dbo.ClaimDischargeSummary','U') IS NOT NULL DROP TABLE dbo.ClaimDischargeSummary;
IF OBJECT_ID('dbo.Policies','U') IS NOT NULL DROP TABLE dbo.Policies;
IF OBJECT_ID('dbo.Claimants','U') IS NOT NULL DROP TABLE dbo.Claimants;
GO

CREATE TABLE dbo.Claimants (
    ClaimantID          VARCHAR(10)   NOT NULL PRIMARY KEY,
    FullName            VARCHAR(100)  NOT NULL,
    DOB                 DATE          NOT NULL,
    Phone               VARCHAR(30)   NOT NULL,
    Email                VARCHAR(120)  NOT NULL,
    Address              VARCHAR(250)  NOT NULL,
    NationalIDType       VARCHAR(10)   NOT NULL,
    NationalID           VARCHAR(30)   NOT NULL
);
GO

CREATE TABLE dbo.Policies (
    PolicyNumber          VARCHAR(15)   NOT NULL PRIMARY KEY,
    ClaimantID             VARCHAR(10)   NOT NULL FOREIGN KEY REFERENCES dbo.Claimants(ClaimantID),
    SumInsured              DECIMAL(12,2) NOT NULL,
    Currency                VARCHAR(5)    NOT NULL,
    PolicyStartDate         DATE          NOT NULL,
    PolicyEndDate           DATE          NOT NULL,
    PreExistingConditions    VARCHAR(200)  NOT NULL,
    RoomRentDailyCap         DECIMAL(12,2) NOT NULL,
    DeductibleAmount         DECIMAL(12,2) NOT NULL,
    CopayPercent             DECIMAL(5,2)  NOT NULL,
    WaitingPeriodMonths      INT           NOT NULL
);
GO

CREATE TABLE dbo.ClaimDischargeSummary (
    ClaimID              VARCHAR(15)   NOT NULL PRIMARY KEY,
    PolicyNumber          VARCHAR(15)   NOT NULL FOREIGN KEY REFERENCES dbo.Policies(PolicyNumber),
    AdmissionDate          DATE          NOT NULL,
    DischargeDate          DATE          NOT NULL,
    LengthOfStayDays       INT           NOT NULL,
    AttendingDoctor        VARCHAR(100)  NOT NULL,
    ICD10Code               VARCHAR(10)   NOT NULL,
    ICD10Description         VARCHAR(150)  NOT NULL,
    ProcedurePerformed        VARCHAR(200)  NOT NULL,
    TreatmentNotes           VARCHAR(1000) NOT NULL
);
GO

CREATE TABLE dbo.ClaimBills (
    InvoiceNumber        VARCHAR(20)   NOT NULL PRIMARY KEY,
    ClaimID               VARCHAR(15)   NOT NULL FOREIGN KEY REFERENCES dbo.ClaimDischargeSummary(ClaimID),
    InvoiceDate            DATE          NOT NULL,
    RoomRentPerDay          DECIMAL(12,2) NOT NULL,
    RoomRentTotal            DECIMAL(12,2) NOT NULL,
    ICUDays                  INT           NOT NULL,
    ICUCharges                DECIMAL(12,2) NOT NULL,
    SurgeryFee                 DECIMAL(12,2) NOT NULL,
    PharmacyCosts              DECIMAL(12,2) NOT NULL,
    Tax                          DECIMAL(12,2) NOT NULL,
    TotalAmount                  DECIMAL(12,2) NOT NULL,
    Currency                      VARCHAR(5)    NOT NULL
);
GO

CREATE TABLE dbo.ClaimSupportingDocs (
    DocID                 INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    ClaimID                VARCHAR(15)   NOT NULL FOREIGN KEY REFERENCES dbo.ClaimDischargeSummary(ClaimID),
    DocType                 VARCHAR(50)   NOT NULL,
    DocDetails                VARCHAR(1000) NOT NULL
);
GO

CREATE TABLE dbo.AIUnderwritingEvaluation (
    ClaimID                VARCHAR(15)   NOT NULL PRIMARY KEY FOREIGN KEY REFERENCES dbo.ClaimDischargeSummary(ClaimID),
    RiskScore                INT           NOT NULL,
    FraudDetectorScore         INT           NOT NULL,
    DiscrepancyNotes             VARCHAR(1500) NOT NULL,
    ExecutiveAISummary             VARCHAR(1000) NOT NULL,
    RecommendedDecision              VARCHAR(20)   NOT NULL,
    CitedPolicyClause                  VARCHAR(500)  NOT NULL
);
GO

